// Runs `claude plugin eval` on two plugin folders, one after the other, and prints the verdict.
// The process runner and the output are parameters, so a test replaces them with fakes.

import path from "node:path";
import { armHeading, evalArgs, verdict } from "../domain/compare.ts";
import { runProgram, type Spawn, spawnSyncOrNull } from "./run-program.ts";

/** Runs the eval on one plugin folder. Returns its exit code, or 1 when the run cannot start. */
const evalOf = (
  plugin: string,
  opts: string[],
  spawn: Spawn,
  log: (line: string) => void,
): number => {
  try {
    return (
      runProgram("claude", evalArgs(plugin, opts), { stdio: "inherit" }, spawn)
        ?.exitCode ?? 1
    );
  } catch (err) {
    // A word that a Windows shell cannot take safely: say why, and count the run as failed.
    log((err as Error).message);
    return 1;
  }
};

/**
 * Runs the eval on `a`, then on `b`. Returns 0 when both succeed, else 1.
 * `spawn` and `log` are the process runner and the output, which a test replaces with fakes.
 */
export const runBoth = (
  a: string,
  b: string,
  rest: string[],
  spawn: Spawn = spawnSyncOrNull,
  log: (line: string) => void = console.log,
): number => {
  const first = path.resolve(a);
  const second = path.resolve(b);
  log(armHeading("A", first));
  const x = evalOf(first, rest, spawn, log);
  log(armHeading("B", second));
  const y = evalOf(second, rest, spawn, log);
  const result = verdict(x, y);
  for (const line of result.lines) log(line);
  return result.code;
};
